Do 'LoadGridState' Do Case Case &DDOName.ToUpper() = !'DDO_LOCDESCRICAO' Do 'LoadlocDescricaoOptions' Case &DDOName.ToUpper() = !'DDO_LOCTELEFONE' Do 'LoadlocTelefoneOptions' Case &DDOName.ToUpper() = !'DDO_LOCBAIRRO' Do 'LoadlocBairroOptions' Case &DDOName.ToUpper() = !'DDO_LOCUSUARIO' Do 'LoadlocUsuarioOptions' EndCase
