Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnslocalWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnslocalWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnslocalWWGridState")) Endif
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFLOCCODIGO" &TFlocCodigo.FromString(&GridStateFilterValue.Value) &TFlocCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFLOCCODIGOLARGADA" &TFlocCodigoLargada.FromString(&GridStateFilterValue.Value) &TFlocCodigoLargada_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFLOCDESCRICAO" &TFlocDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLOCDESCRICAO_SEL" &TFlocDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLOCTIPOUNIDADE_SEL" &TFlocTipoUnidade_SelsJson = &GridStateFilterValue.Value &TFlocTipoUnidade_Sels.FromJson(&TFlocTipoUnidade_SelsJson) Case &GridStateFilterValue.Name = !"TFLOCTELEFONE" &TFlocTelefone.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLOCTELEFONE_SEL" &TFlocTelefone_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLOCBAIRRO" &TFlocBairro.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLOCBAIRRO_SEL" &TFlocBairro_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLOCUSUARIO" &TFlocUsuario.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLOCUSUARIO_SEL" &TFlocUsuario_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLOCFORNO_SEL" &TFlocForno_SelsJson = &GridStateFilterValue.Value &TFlocForno_Sels.FromJson(&TFlocForno_SelsJson) Case &GridStateFilterValue.Name = !"TFLOCNOTA" &TFlocNota.FromString(&GridStateFilterValue.Value) &TFlocNota_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFLOCSTATUS_SEL" &TFlocStatus_SelsJson = &GridStateFilterValue.Value &TFlocStatus_Sels.FromJson(&TFlocStatus_SelsJson) Case &GridStateFilterValue.Name = !"TFLOCUECOD" &TFlocUeCod.FromString(&GridStateFilterValue.Value) &TFlocUeCod_To.FromString(&GridStateFilterValue.ValueTo) EndCase EndFor If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'LOCDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &locDescricao1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'LOCCODIGOLARGADA' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &locCodigoLargada1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'LOCCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &locCodigo1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'LOCEMAIL' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &locEmail1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'LOCFREEZER' &locFreezer1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'LOCFORNO' &locForno1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'LOCTELEFONE' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &locTelefone1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'LOCBAIRRO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &locBairro1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'LOCTIPOUNIDADE' &locTipoUnidade1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'LOCNOTA' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &locNota1.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'LOCDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &locDescricao2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'LOCCODIGOLARGADA' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &locCodigoLargada2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'LOCCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &locCodigo2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'LOCEMAIL' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &locEmail2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'LOCFREEZER' &locFreezer2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'LOCFORNO' &locForno2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'LOCTELEFONE' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &locTelefone2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'LOCBAIRRO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &locBairro2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'LOCTIPOUNIDADE' &locTipoUnidade2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'LOCNOTA' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &locNota2.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'LOCDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &locDescricao3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'LOCCODIGOLARGADA' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &locCodigoLargada3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'LOCCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &locCodigo3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'LOCEMAIL' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &locEmail3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'LOCFREEZER' &locFreezer3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'LOCFORNO' &locForno3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'LOCTELEFONE' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &locTelefone3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'LOCBAIRRO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &locBairro3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'LOCTIPOUNIDADE' &locTipoUnidade3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'LOCNOTA' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &locNota3.FromString(&GridStateDynamicFilter.Value) EndCase EndIf EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadlocDescricaoOptions'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&TFlocDescricao = &SearchTxt &TFlocDescricao_Sel.SetEmpty() For Each trnslocal Order locDescricao using trnslocalWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &locDescricao1, &locCodigoLargada1, &locCodigo1, &locEmail1 , &locFreezer1, &locForno1, &locTelefone1, &locBairro1, &locTipoUnidade1, &locNota1 , &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &locDescricao2, &locCodigoLargada2, &locCodigo2 , &locEmail2, &locFreezer2, &locForno2, &locTelefone2, &locBairro2, &locTipoUnidade2 , &locNota2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &locDescricao3, &locCodigoLargada3 , &locCodigo3, &locEmail3, &locFreezer3, &locForno3, &locTelefone3, &locBairro3 , &locTipoUnidade3, &locNota3, &TFlocCodigo, &TFlocCodigo_To, &TFlocCodigoLargada, &TFlocCodigoLargada_To , &TFlocDescricao, &TFlocDescricao_Sel, &TFlocTipoUnidade_Sels, &TFlocTelefone, &TFlocTelefone_Sel, &TFlocBairro , &TFlocBairro_Sel, &TFlocUsuario, &TFlocUsuario_Sel, &TFlocForno_Sels, &TFlocNota, &TFlocNota_To , &TFlocStatus_Sels, &TFlocUeCod, &TFlocUeCod_To) Where prefCodigo = &prefCodigo
&count = 0 For Each trnslocal Order locDescricao &count += 1 EndFor If not locDescricao.IsEmpty() &Option = locDescricao
&Options.Add(&Option) &OptionIndexes.Add(trim(&count.ToFormattedString())) EndIf If &Options.Count = 50 Exit EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
